(function() {
	//#region src/Modules/CrestApps.OrchardCore.Stripe/Assets/js/stripe-checkout-payment.js
	(function() {
		"use strict";
		function initialize(options) {
			if (typeof checkoutPayment === "undefined" || !options || !options.publishableKey) return;
			var stripe = Stripe(options.publishableKey);
			var card = stripe.elements().create("card");
			card.mount(options.cardElementSelector);
			var errorElement = document.querySelector(options.errorSelector);
			card.on("change", function(event) {
				if (errorElement) {
					errorElement.textContent = event.error ? event.error.message : "";
					errorElement.classList.toggle("d-none", !event.error);
				}
			});
			var preparedPaymentMethodId = null;
			function billingName() {
				return options.nameElement ? (document.querySelector(options.nameElement) || {}).value || "" : "";
			}
			function showError(message) {
				if (errorElement) {
					errorElement.textContent = message;
					errorElement.classList.remove("d-none");
				}
			}
			var walletPaymentMethodId = null;
			function needsReusablePaymentMethod() {
				return options.hasRecurringItems || options.savePaymentMethod;
			}
			function paymentMethodData(paymentMethodId) {
				var data = { paymentMethodId };
				if (options.savePaymentMethod) data.savePaymentMethod = "true";
				return data;
			}
			mountWallets();
			var savedCards = options.savedCardsSelector ? document.querySelector(options.savedCardsSelector) : null;
			var newCard = options.newCardSelector ? document.querySelector(options.newCardSelector) : null;
			var rememberCard = options.rememberCardSelector ? document.querySelector(options.rememberCardSelector) : null;
			function selectedSavedCard() {
				var checked = savedCards ? savedCards.querySelector("input[type=radio]:checked") : null;
				return checked ? checked.value : "";
			}
			function syncSavedCards() {
				if (newCard) newCard.classList.toggle("d-none", !!selectedSavedCard());
			}
			if (savedCards) {
				savedCards.addEventListener("change", syncSavedCards);
				syncSavedCards();
			}
			function mountWallets() {
				var container = options.walletSelector ? document.querySelector(options.walletSelector) : null;
				if (!container || !options.walletAmount || !options.walletCurrency) return;
				var elementsOptions = {
					mode: "payment",
					amount: options.walletAmount,
					currency: options.walletCurrency,
					paymentMethodCreation: "manual"
				};
				if (needsReusablePaymentMethod()) elementsOptions.setupFutureUsage = "off_session";
				var walletElements = stripe.elements(elementsOptions);
				var express = walletElements.create("expressCheckout", {
					paymentMethods: {
						applePay: "auto",
						googlePay: "auto",
						link: "never",
						paypal: "never",
						amazonPay: "never",
						klarna: "never"
					},
					buttonHeight: 48
				});
				express.on("ready", function(event) {
					container.classList.toggle("d-none", !event.availablePaymentMethods);
				});
				express.on("confirm", async function(event) {
					var submitted = await walletElements.submit();
					if (submitted.error) {
						showError(submitted.error.message);
						return;
					}
					var created = await stripe.createPaymentMethod({
						elements: walletElements,
						params: { billing_details: event.billingDetails || {} }
					});
					if (created.error) {
						event.paymentFailed({ reason: "fail" });
						showError(created.error.message);
						return;
					}
					walletPaymentMethodId = created.paymentMethod.id;
					try {
						if (!await checkoutPayment.submit(options.processorKey)) try {
							event.paymentFailed({ reason: "fail" });
						} catch (e) {}
					} finally {
						walletPaymentMethodId = null;
					}
				});
				express.mount(options.walletButtonsSelector);
			}
			checkoutPayment.register(options.processorKey, {
				prepare: async function() {
					var savedCardId = selectedSavedCard();
					if (savedCardId && !walletPaymentMethodId) {
						preparedPaymentMethodId = savedCardId;
						return { savedCardId };
					}
					if (walletPaymentMethodId) {
						preparedPaymentMethodId = walletPaymentMethodId;
						return needsReusablePaymentMethod() ? paymentMethodData(preparedPaymentMethodId) : null;
					}
					preparedPaymentMethodId = null;
					var remember = !!(rememberCard && rememberCard.checked);
					if (!needsReusablePaymentMethod() && !remember) return null;
					var result = await stripe.createPaymentMethod({
						type: "card",
						card,
						billing_details: { name: billingName() }
					});
					if (result.error) {
						showError(result.error.message);
						return false;
					}
					preparedPaymentMethodId = result.paymentMethod.id;
					if (remember && !needsReusablePaymentMethod()) return {
						paymentMethodId: preparedPaymentMethodId,
						rememberCard: "true"
					};
					return paymentMethodData(preparedPaymentMethodId);
				},
				confirm: async function(step) {
					if (!step.clientSecret) return true;
					var result = await stripe.confirmCardPayment(step.clientSecret, { payment_method: preparedPaymentMethodId || {
						card,
						billing_details: { name: billingName() }
					} });
					if (result.error) {
						showError(result.error.message);
						return false;
					}
					return true;
				}
			});
		}
		window.stripeCheckoutPayment = { initialize };
	})();
	//#endregion
})();
